public struct APIAssistantClient: Sendable {
    private let client: APIClient

    init(client: APIClient) {
        self.client = client
    }

    /// Stream an assistant reply, exercises a server-sent events response
    public func reply(_ body: APIClient.AssistantReply.Body) async throws(APIClient.AssistantReply.Failure) -> APIClient.AssistantReply.Result {
        let path = "/assistant/reply"
        let url = try Kizuna.makeURL(baseURL: client.baseURL, path: path, queryItems: [], failure: APIClient.AssistantReply.Failure.self)
        var request = URLRequest(url: url, cachePolicy: .useProtocolCachePolicy, timeoutInterval: client.timeout)
        request.httpMethod = "POST"
        for (name, value) in client.requestContextHeaders { request.setValue(value, forHTTPHeaderField: name) }
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        try Kizuna.encodeBody(&request, value: body.payload, using: client.encoder, failure: APIClient.AssistantReply.Failure.self)
        let (bytes, statusCode, _) = try await Kizuna.open(&request, session: client.session, requestMiddleware: client.requestMiddleware, failure: APIClient.AssistantReply.Failure.self)
        switch statusCode {
        case 200:
            let body = Kizuna.events(bytes, using: client.decoder) { event, decoder -> APIClient.AssistantReply.Event? in
                switch event.event {
                case "delta": return .delta(try decoder.decode(APIClient.AssistantReply.Delta.self, from: Foundation.Data(event.data.utf8)))
                case "done": return .done(try decoder.decode(APIClient.AssistantReply.Done.self, from: Foundation.Data(event.data.utf8)))
                case "tool_call": return .tool_call(try decoder.decode(APIClient.AssistantReply.ToolCall.self, from: Foundation.Data(event.data.utf8)))
                case "tool_result": return .tool_result(try decoder.decode(APIClient.AssistantReply.ToolResult.self, from: Foundation.Data(event.data.utf8)))
                case "tool_error": return .tool_error(try decoder.decode(APIClient.AssistantReply.ToolError.self, from: Foundation.Data(event.data.utf8)))
                default: return nil
                }
            }
            return APIClient.AssistantReply.Result(body: body)
        case 400:
            let data = try await Kizuna.collect(bytes, failure: APIClient.AssistantReply.Failure.self)
            throw Kizuna.firstError(statusCode: statusCode, data: data, [
                { (try? client.decoder.decode(API.ProblemDetails.self, from: data)).map(APIClient.AssistantReply.Failure.badRequest) },
                { (try? client.decoder.decode(APIClient.ValidationError.self, from: data)).map(APIClient.AssistantReply.Failure.validationError) },
            ])
        default:
            let data = try await Kizuna.collect(bytes, failure: APIClient.AssistantReply.Failure.self)
            throw APIClient.AssistantReply.Failure.unexpectedStatus(statusCode, data)
        }
    }
}

public protocol KizunaFailure: Swift.Error {
    static func requestFailed(_ error: Swift.Error) -> Self
    static var invalidRequest: Self { get }
    static var cancelled: Self { get }
    static var invalidResponse: Self { get }
    static func unexpectedStatus(_ status: Int, _ data: Foundation.Data) -> Self
    var isCancelled: Bool { get }
}

public protocol KizunaDecodableFailure: KizunaFailure {
    static func decoding(_ error: Swift.Error, statusCode: Int, data: Foundation.Data) -> Self
}

private enum Kizuna {
    @Sendable static func decodeDate(_ decoder: Decoder) throws -> Date {
        let container = try decoder.singleValueContainer()
        let raw = try container.decode(String.self)
        if let date = try? Date(raw, strategy: Date.ISO8601FormatStyle(includingFractionalSeconds: true)) { return date }
        if let date = try? Date(raw, strategy: Date.ISO8601FormatStyle()) { return date }
        throw DecodingError.dataCorruptedError(in: container, debugDescription: "Invalid ISO8601 date: \(raw)")
    }

    static func encodeDate(_ date: Date) -> String {
        date.formatted(Date.ISO8601FormatStyle(includingFractionalSeconds: true))
    }

    static func makeJSONEncoder() -> JSONEncoder {
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .custom { date, encoder in
            var container = encoder.singleValueContainer()
            try container.encode(encodeDate(date))
        }
        return encoder
    }

    static func makeJSONDecoder() -> JSONDecoder {
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .custom(decodeDate)
        return decoder
    }

    private static let pathSegmentAllowed: CharacterSet = {
        var allowed = CharacterSet.urlPathAllowed
        allowed.remove(charactersIn: "/")
        return allowed
    }()

    static func encodePathSegment<Value>(_ value: Value) -> String {
        let text = stringifyQueryValue(value).first ?? ""
        return text.addingPercentEncoding(withAllowedCharacters: pathSegmentAllowed) ?? text
    }

    static func appendPath(_ base: URL, _ path: String) -> URL {
        base.appending(path: path, directoryHint: .notDirectory)
    }

    static func stringifyQueryValue(_ value: Any) -> [String] {
        switch value {
        case let date as Date:
            return [encodeDate(date)]
        case let array as [Any]:
            return array.flatMap { stringifyQueryValue($0) }
        case let raw as any RawRepresentable where raw.rawValue is CustomStringConvertible:
            return [String(describing: raw.rawValue)]
        case let convertible as CustomStringConvertible:
            return [convertible.description]
        default:
            return [String(describing: value)]
        }
    }

    static func queryItems<Value>(name: String, value: Value?) -> [URLQueryItem] {
        guard let value else { return [] }
        return stringifyQueryValue(value).map { URLQueryItem(name: name, value: $0) }
    }

    static func setHeader<Value>(_ request: inout URLRequest, name: String, value: Value?) {
        guard let value else { return }
        request.setValue(stringifyQueryValue(value).joined(separator: ", "), forHTTPHeaderField: name)
    }

    static func makeURL<Failure: KizunaFailure>(baseURL: URL, path: String, queryItems: [URLQueryItem], failure: Failure.Type) throws(Failure) -> URL {
        guard var components = URLComponents(url: appendPath(baseURL, path), resolvingAgainstBaseURL: false) else {
            throw Failure.invalidRequest
        }
        if !queryItems.isEmpty { components.queryItems = queryItems }
        guard let url = components.url else { throw Failure.invalidRequest }
        return url
    }

    static func encodeBody<Value: Encodable, Failure: KizunaFailure>(_ request: inout URLRequest, value: Value, using encoder: JSONEncoder, failure: Failure.Type) throws(Failure) {
        do { request.httpBody = try encoder.encode(value) }
        catch { throw Failure.requestFailed(error) }
    }

    static func send<Failure: KizunaFailure>(_ request: inout URLRequest, session: URLSession, requestMiddleware: (@Sendable (inout URLRequest) async throws -> Void)?, responseMiddleware: (@Sendable (URLRequest, Foundation.Data, URLResponse) async -> Void)?, failure: Failure.Type) async throws(Failure) -> (Foundation.Data, Int, HTTPURLResponse) {
        if let requestMiddleware {
            do { try await requestMiddleware(&request) }
            catch is CancellationError { throw Failure.cancelled }
            catch let error as URLError where error.code == .cancelled { throw Failure.cancelled }
            catch { throw Failure.requestFailed(error) }
        }
        let data: Foundation.Data
        let response: URLResponse
        do { (data, response) = try await session.data(for: request) }
        catch is CancellationError { throw Failure.cancelled }
        catch let error as URLError where error.code == .cancelled { throw Failure.cancelled }
        catch { throw Failure.requestFailed(error) }
        if let responseMiddleware { await responseMiddleware(request, data, response) }
        guard let httpResponse = response as? HTTPURLResponse else { throw Failure.invalidResponse }
        return (data, httpResponse.statusCode, httpResponse)
    }

    static func decode<Value: Decodable, Failure: KizunaDecodableFailure>(_ type: Value.Type, from data: Foundation.Data, using decoder: JSONDecoder, statusCode: Int, failure: Failure.Type) throws(Failure) -> Value {
        do { return try decoder.decode(Value.self, from: data) }
        catch { throw Failure.decoding(error, statusCode: statusCode, data: data) }
    }

    static func firstError<Failure: KizunaDecodableFailure>(statusCode: Int, data: Foundation.Data, _ attempts: [() -> Failure?]) -> Failure {
        for attempt in attempts {
            if let failure = attempt() { return failure }
        }
        return Failure.decoding(DecodingError.dataCorrupted(.init(codingPath: [], debugDescription: "No matching type for status \(statusCode)")), statusCode: statusCode, data: data)
    }

    struct ServerSentEvent: Sendable {
        let event: String?
        let data: String
        let id: String?
        let retry: Int?
    }

    static func open<Failure: KizunaFailure>(_ request: inout URLRequest, session: URLSession, requestMiddleware: (@Sendable (inout URLRequest) async throws -> Void)?, failure: Failure.Type) async throws(Failure) -> (URLSession.AsyncBytes, Int, HTTPURLResponse) {
        if let requestMiddleware {
            do { try await requestMiddleware(&request) }
            catch is CancellationError { throw Failure.cancelled }
            catch let error as URLError where error.code == .cancelled { throw Failure.cancelled }
            catch { throw Failure.requestFailed(error) }
        }
        let bytes: URLSession.AsyncBytes
        let response: URLResponse
        do { (bytes, response) = try await session.bytes(for: request) }
        catch is CancellationError { throw Failure.cancelled }
        catch let error as URLError where error.code == .cancelled { throw Failure.cancelled }
        catch { throw Failure.requestFailed(error) }
        guard let httpResponse = response as? HTTPURLResponse else { throw Failure.invalidResponse }
        return (bytes, httpResponse.statusCode, httpResponse)
    }

    static func collect<Failure: KizunaFailure>(_ bytes: URLSession.AsyncBytes, failure: Failure.Type) async throws(Failure) -> Foundation.Data {
        var data = Foundation.Data()
        do { for try await byte in bytes { data.append(byte) } }
        catch is CancellationError { throw Failure.cancelled }
        catch { throw Failure.requestFailed(error) }
        return data
    }

    static func lines(_ bytes: URLSession.AsyncBytes) -> AsyncThrowingStream<String, Swift.Error> {
        AsyncThrowingStream { continuation in
            let task = Task {
                var buffer: [UInt8] = []
                var pendingCarriageReturn = false
                do {
                    for try await byte in bytes {
                        if pendingCarriageReturn {
                            pendingCarriageReturn = false
                            if byte == 0x0A { continue }
                        }
                        if byte == 0x0A || byte == 0x0D {
                            pendingCarriageReturn = byte == 0x0D
                            continuation.yield(String(decoding: buffer, as: UTF8.self))
                            buffer.removeAll(keepingCapacity: true)
                            continue
                        }
                        buffer.append(byte)
                    }
                    if !buffer.isEmpty { continuation.yield(String(decoding: buffer, as: UTF8.self)) }
                    continuation.finish()
                }
                catch { continuation.finish(throwing: error) }
            }
            continuation.onTermination = { _ in task.cancel() }
        }
    }

    static func chunks(_ bytes: URLSession.AsyncBytes) -> AsyncThrowingStream<Foundation.Data, Swift.Error> {
        AsyncThrowingStream { continuation in
            let task = Task {
                var buffer = Foundation.Data()
                do {
                    for try await byte in bytes {
                        buffer.append(byte)
                        if buffer.count >= 16_384 {
                            continuation.yield(buffer)
                            buffer = Foundation.Data()
                        }
                    }
                    if !buffer.isEmpty { continuation.yield(buffer) }
                    continuation.finish()
                }
                catch { continuation.finish(throwing: error) }
            }
            continuation.onTermination = { _ in task.cancel() }
        }
    }

    static func serverSentEvents(_ bytes: URLSession.AsyncBytes) -> AsyncThrowingStream<ServerSentEvent, Swift.Error> {
        AsyncThrowingStream { continuation in
            let task = Task {
                var eventType = ""
                var dataLines: [String] = []
                var lastEventId = ""
                var retry: Int? = nil
                do {
                    for try await line in lines(bytes) {
                        if line.isEmpty {
                            if !dataLines.isEmpty {
                                continuation.yield(ServerSentEvent(event: eventType.isEmpty ? nil : eventType, data: dataLines.joined(separator: "\n"), id: lastEventId.isEmpty ? nil : lastEventId, retry: retry))
                                dataLines = []
                                retry = nil
                            }
                            eventType = ""
                            continue
                        }
                        if line.hasPrefix(":") { continue }
                        let field: Substring
                        var value: Substring
                        if let separator = line.firstIndex(of: ":") {
                            field = line[..<separator]
                            value = line[line.index(after: separator)...]
                            if value.hasPrefix(" ") { value = value.dropFirst() }
                        } else {
                            field = Substring(line)
                            value = ""
                        }
                        switch field {
                        case "event": eventType = String(value)
                        case "data": dataLines.append(String(value))
                        case "id": if !value.contains("\0") { lastEventId = String(value) }
                        case "retry": if !value.isEmpty, value.allSatisfy(\.isNumber), let milliseconds = Int(value) { retry = milliseconds }
                        default: break
                        }
                    }
                    continuation.finish()
                }
                catch { continuation.finish(throwing: error) }
            }
            continuation.onTermination = { _ in task.cancel() }
        }
    }

    static func events<Event: Sendable>(_ bytes: URLSession.AsyncBytes, using decoder: JSONDecoder, _ decode: @escaping @Sendable (ServerSentEvent, JSONDecoder) throws -> Event?) -> AsyncThrowingStream<Event, Swift.Error> {
        AsyncThrowingStream { continuation in
            let task = Task {
                do {
                    for try await event in serverSentEvents(bytes) {
                        if let decoded = try decode(event, decoder) { continuation.yield(decoded) }
                    }
                    continuation.finish()
                }
                catch { continuation.finish(throwing: error) }
            }
            continuation.onTermination = { _ in task.cancel() }
        }
    }

    struct MultipartBuilder {
        let boundary: String
        private var data = Foundation.Data()

        init(boundary: String = "kizuna-\(UUID().uuidString)") {
            self.boundary = boundary
        }

        mutating func appendField(name: String, value: String) {
            data.append("--\(boundary)\r\n".data(using: .utf8)!)
            data.append("Content-Disposition: form-data; name=\"\(name)\"\r\n\r\n".data(using: .utf8)!)
            data.append(value.data(using: .utf8)!)
            data.append("\r\n".data(using: .utf8)!)
        }

        mutating func appendFile(name: String, file: APIClient.MultipartFile) {
            data.append("--\(boundary)\r\n".data(using: .utf8)!)
            data.append("Content-Disposition: form-data; name=\"\(name)\"; filename=\"\(file.filename)\"\r\n".data(using: .utf8)!)
            data.append("Content-Type: \(file.mimeType)\r\n\r\n".data(using: .utf8)!)
            data.append(file.data)
            data.append("\r\n".data(using: .utf8)!)
        }

        func finalize() -> Foundation.Data {
            var result = data
            result.append("--\(boundary)--\r\n".data(using: .utf8)!)
            return result
        }

        var contentType: String {
            "multipart/form-data; boundary=\(boundary)"
        }
    }
}
